import React, { useState, useMemo, useEffect } from "react";
import { useSearchParams } from "react-router-dom";
import MatchItem from "./MatchItem";

function MatchList({ matches, selectedLeague, orderedLeagues }) {
  const [searchParams] = useSearchParams();
  const searchQuery = searchParams.get("search")?.toLowerCase() || "";

  // По умолчанию null - показываем ВСЕ, что прислал сервер
  const [selectedDate, setSelectedDate] = useState(null);

  // Кнопки дат (Вчера, Сегодня + 5 дней)
  const dateOptions = useMemo(() => {
    const dates = [];
    for (let i = -1; i <= 5; i++) {
      const d = new Date();
      d.setDate(d.getDate() + i);
      dates.push({
        full: d.toISOString().split("T")[0],
        day: d.getDate(),
        weekday: d.toLocaleDateString("ru-RU", { weekday: "short" }),
      });
    }
    return dates;
  }, []);

  // --- ЛОГИКА ФИЛЬТРАЦИИ ---
  const filteredMatches = useMemo(() => {
    let result = [...matches];

    // 1. Поиск
    if (searchQuery) {
      result = result.filter(
        (m) =>
          m.homeTeam.name.toLowerCase().includes(searchQuery) ||
          m.awayTeam.name.toLowerCase().includes(searchQuery) ||
          (m.homeTeam.name_ru &&
            m.homeTeam.name_ru.toLowerCase().includes(searchQuery)),
      );
    }

    // 2. Лига
    if (selectedLeague) {
      result = result.filter((m) => m.league === selectedLeague);
    }

    // 3. Дата (с защитой от ошибок формата)
    /*if (selectedDate) {
      result = result.filter((m) => {
        if (!m.utcDate) return false;
        return m.utcDate.substring(0, 10) === selectedDate;
      });
    }*/

    return result;
  }, [matches, selectedLeague, selectedDate, searchQuery]);

  // --- ЛОГИКА ГРУППИРОВКИ (БЕЗОПАСНАЯ) ---
  const groupedMatches = useMemo(() => {
    const groups = {};

    filteredMatches.forEach((match) => {
      const leagueCode = match.league;
      if (!groups[leagueCode]) {
        // Ищем лигу в нашем списке из хедера
        const leagueObj = orderedLeagues.find(
          (l) => l.code === leagueCode || l.name === leagueCode,
        );

        groups[leagueCode] = {
          name: leagueObj ? leagueObj.name : leagueCode,
          // Если лига не найдена в списке - ставим её в конец (999)
          order: leagueObj ? orderedLeagues.indexOf(leagueObj) : 999,
          matches: [],
        };
      }
      groups[leagueCode].matches.push(match);
    });

    // ПРАВИЛЬНАЯ СОРТИРОВКА: исключаем ошибки с undefined
    return Object.entries(groups).sort((a, b) => {
      return (a[1].order || 0) - (b[1].order || 0);
    });
  }, [filteredMatches, orderedLeagues]);

  const formatErrorDate = (dateStr) => {
    if (!dateStr) return "";
    const [y, m, d] = dateStr.split("-");
    return `${d}-${m}-${y}`;
  };

  return (
    <div className="w-full">
      {/* ПАНЕЛЬ ДАТ */}
      {!searchQuery && (
        <div className="flex items-stretch gap-1 md:gap-2 mb-12 mt-0 bg-gray-900/40 p-1.5 rounded-b-2xl border-x border-b border-gray-800 w-full overflow-x-auto no-scrollbar">
          <button
            onClick={() => setSelectedDate(null)}
            className={`flex-1 flex items-center justify-center px-6 h-14 rounded-xl font-black text-[9px] uppercase transition-all ${selectedDate === null ? "bg-red-600 text-white shadow-lg" : "bg-gray-800 text-gray-500 hover:bg-gray-700"}`}
          >
            ВСЕ
          </button>
          {dateOptions.map((d) => (
            <button
              key={d.full}
              onClick={() => setSelectedDate(d.full)}
              className={`flex-1 flex flex-col items-center justify-center min-w-[60px] h-14 rounded-xl transition-all ${selectedDate === d.full ? "bg-red-600 text-white shadow-lg" : "bg-gray-800 text-gray-500 hover:bg-gray-700"}`}
            >
              <span className="text-[8px] font-black uppercase mb-1">
                {d.weekday}
              </span>
              <span className="text-sm font-black">{d.day}</span>
            </button>
          ))}
          <div className="relative flex-shrink-0 ml-1">
            <input
              type="date"
              className="absolute inset-0 opacity-0 cursor-pointer z-10"
              onChange={(e) => setSelectedDate(e.target.value)}
            />
            <button
              className={`w-12 h-14 flex items-center justify-center rounded-xl ${selectedDate && !dateOptions.find((d) => d.full === selectedDate) ? "bg-red-600 text-white" : "bg-gray-800 text-gray-500"}`}
            >
              <svg
                className="w-5 h-5"
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth="2"
                  d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z"
                />
              </svg>
            </button>
          </div>
        </div>
      )}

      {/* ВЫВОД МАТЧЕЙ */}
      {groupedMatches.length === 0 ? (
        <div className="text-center py-20 bg-gray-900/20 rounded-3xl border border-gray-800/50 px-6">
          <h3 className="text-white font-black uppercase tracking-tighter text-lg mb-2">
            {searchQuery
              ? `Команда "${searchQuery}" не найдена`
              : `Матчей на ${formatErrorDate(selectedDate)} не найдено`}
          </h3>
          <p className="text-gray-500 text-[10px] font-bold uppercase tracking-widest leading-relaxed">
            Попробуйте нажать кнопку "ВСЕ" <br /> или воспользуйтесь календарем.
          </p>
        </div>
      ) : (
        groupedMatches.map(([code, league]) => (
          <div key={code} className="mb-14">
            <div className="flex flex-col items-center mb-8">
              <h2 className="text-2xl font-black text-white uppercase tracking-tighter italic">
                {league.name}
              </h2>
              <div className="w-16 h-1 bg-red-600 mt-2 rounded-full opacity-40 shadow-[0_0_10px_red]"></div>
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-3 gap-6">
              {league.matches.map((match) => (
                <MatchItem key={match.id} match={match} />
              ))}
            </div>
          </div>
        ))
      )}
    </div>
  );
}

export default MatchList;
